import re

new_belov_card = """        <!-- 4. БЕЛОВ -->
        <div class="surname-card" id="surname-belov">
          <div class="surname-kicker">🌾 Ветвь мамы · Закамская засечная черта (с. Никольское / Жукотино / Галактионово)</div>
          <h3 class="surname-title">Беловы (род прабабушки Агриппины Александровны)</h3>
          <div class="surname-etym">
            <p style="margin:0 0 8px;"><b>1. Древнерусское имя Белой (Беляй) и «обелённые крестьяне» Закамской черты:</b> Фамилия восходит к охранному мирскому имени <i>Белой / Беляй</i> (светловолосый, белолицый, чистый духом человек). Второй важнейший региональный источник фамилии на Каме — статус <b>«обеленного крестьянина / беломестца»</b>: в середине XVII века крестьяне села Жукотино («Савин Городок»), нёсшие дозорную сторожевую службу на Закамской засечной черте (1652–1656 гг.) после разорительного набега ногайцев 1654 года, освобождались («обелялись») царским указом от государева тягла.</p>
            <p style="margin:0 0 8px;"><b>2. Родовое гнездо — вотчина дворян Аристовых «Савин Городок»:</b> Село основано в конце 1630-х – начале 1640-х гг. казанским дворянином <b>Саввой Тимофеевичем Аристовым</b> у стен древнего булгарского городища Джукетау (Жукотин) на р. Каме и р. Прость. Помещики Аристовы непрерывно владели крестьянами села на протяжении двух веков — вплоть до Манифеста 1861 года об отмене крепостного права.</p>
            <p style="margin:0 0 8px;"><b>3. Прапрадед Александр Белов и прабабушка Агриппина:</b> Прапрадед <b>Александр Белов</b> <span class="person-link-chip" onclick="openPersonFromAnywhere('P-0014')">P-0014</span> (р. ок. 1855–1865) воспитал прабабушку <b>Агриппину Александровну Белову</b> <span class="person-link-chip" onclick="openPersonFromAnywhere('P-0008')">P-0008</span> (1889–1971), ставшую матерью-героиней чистопольского рода: она дала жизнь 8 детям и подняла 13 сирот и приёмных детей в тяжелейшие годы Первой мировой, голода и Гражданской войны.</p>
            <p style="margin:0 0 8px;"><b>4. Репрессированная ветвь — старший брат Фёдор Александрович Белов (1887 г.р.):</b> В Книге памяти жертв политических репрессий Республики Татарстан (т. 3) выявлен родной старший брат Агриппины — <b>Белов Фёдор Александрович</b> <span class="person-link-chip" onclick="openPersonFromAnywhere('P-0030')">P-0030</span> (1887 г.р., с. Галактионово, грамотный крестьянин). Прошёл через два ареста: 31.01.1919 (в Гражданскую войну, освобождён) и 17.09.1935 по 58-й статье (ст. 58-10 УК РСФСР, «антисоветская агитация»). 18.01.1936 приговорён Главным судом ТАССР к <b>3 годам лишения свободы</b>; после отбытия наказания жил в дер. Дахново Новгородской области. <b>Полностью реабилитирован 20.01.1997</b> <code>[A-0036]</code>. Подготовлен запрос в архив УФСБ/МВД по РТ на получение анкеты семьи: <a href="queries/13_mvd_rt_belov_fedor_1935_repressii.md" target="_blank" style="color:var(--accent-seal);font-weight:600;text-decoration:underline;">13_mvd_rt_belov.md ↗</a>.</p>
            <p style="margin:0 0 8px;"><b>5. Фронтовая ветвь — артиллерист Павел Белов и старший сын Иван:</b> Сыновья Фёдора Александровича (двоюродные братья деда Александра Николаевича Евдокимова):
              <br/>• <b>Белов Павел Фёдорович</b> <span class="person-link-chip" onclick="openPersonFromAnywhere('P-0031')">P-0031</span> (1914–1979) — гвардии сержант, артиллерист <b>349-го артиллерийского полка 119-й стрелковой дивизии</b>. Призван 05.03.1942 Волжским РВК. Кавалер боевых медалей <b>«За отвагу»</b>, <b>«За боевые заслуги»</b> и «За победу над Германией». Жил и похоронен в г. Волжске <code>[A-0037]</code>.
              <br/>• <b>Белов Иван Фёдорович</b> <span class="person-link-chip" onclick="openPersonFromAnywhere('P-0032')">P-0032</span> (1911 г.р.) — старший сын Фёдора, крестьянин села Галактионово, мобилизован на фронт в марте 1942 г.</p>
            <p style="margin:0;"><b>6. Точные шифры в архивах НА РТ и FamilySearch:</b>
              <br/>• <b>НА РТ (Казань), ф. 3, оп. 2, д. 390 (лл. 36–46):</b> 10-я ревизия 1858 г. помещичьих крестьян с. Жукотино помещиков Аристовых (семья прапрадеда Александра Белова) · <a href="queries/09_nart_kazan_revizii_zhukotino_1834_1858.md" target="_blank" style="color:var(--accent-seal);font-weight:600;text-decoration:underline;">09_nart.md ↗</a>.
              <br/>• <b>НА РТ (Казань), ф. 4, оп. 176:</b> Метрические книги Николаевской церкви с. Жукотино за 1887 и 1889 гг. (рождение Фёдора и Агриппины).
              <br/>• <b>FamilySearch:</b> Метрическая книга 1850 г. Покровской церкви (микрофильм <b>2344399</b> / DGS <b>7439880</b>) и исповедная ведомость 1797 г. Николаевской церкви (DGS <b>007433602</b>) <code>[A-0038]</code>.</p>
          </div>
        </div>"""

for fn in ['dashboard.html', 'index.html']:
    with open(fn, 'r', encoding='utf-8') as f:
        content = f.read()

    pattern = r'<!-- 4\. БЕЛОВ -->\s*<div class="surname-card" id="surname-belov">.*?</div>\s*</div>'
    m = re.search(pattern, content, re.DOTALL)
    if m:
        content = content[:m.start()] + new_belov_card + content[m.end():]
        with open(fn, 'w', encoding='utf-8') as f:
            f.write(content)
        print(f"Updated {fn} with expanded Belov card successfully!")
    else:
        print(f"Could not find Belov card in {fn}")

